+
+    /* MRP_PortRole */
+    offset = dissect_pn_uint16(tvb, offset, pinfo, tree, hf_pn_mrp_port_role, NULL);
+
+    /*MRP_InID*/
+    offset = dissect_pn_uint16(tvb, offset, pinfo, tree, hf_pn_mrp_in_id, NULL);
+
+    return offset;
+}

